import jsPDF from 'jspdf';

export const generateCertificatePDF = (certificateData) => {
  return new Promise((resolve) => {
    const pdf = new jsPDF('landscape', 'mm', 'a4');
    const pageWidth = pdf.internal.pageSize.getWidth();
    
    // Design simple et professionnel
    pdf.setFillColor(248, 250, 252);
    pdf.rect(0, 0, pageWidth, pdf.internal.pageSize.getHeight(), 'F');
    
    pdf.setFontSize(32);
    pdf.setTextColor(59, 130, 246);
    pdf.text('CERTIFICAT DE RÉUSSITE', pageWidth / 2, 50, { align: 'center' });
    
    pdf.setFontSize(16);
    pdf.setTextColor(107, 114, 128);
    pdf.text('Décerné à', pageWidth / 2, 80, { align: 'center' });
    
    pdf.setFontSize(24);
    pdf.setTextColor(31, 41, 55);
    pdf.text(certificateData.studentName, pageWidth / 2, 105, { align: 'center' });
    
    // ... reste du design simplifié
    resolve(pdf.output('blob'));
  });
};

export const downloadPDF = (pdfBlob, fileName = 'certificat.pdf') => {
  const url = URL.createObjectURL(pdfBlob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};
